-- Explicit graph schema installation, version 1. Does not modify any legacy arc_* table.
CREATE TABLE arc_graph_schema (singleton INTEGER PRIMARY KEY, schema_version INTEGER NOT NULL, CONSTRAINT arc_graph_singleton CHECK (singleton = 1));
INSERT INTO arc_graph_schema (singleton, schema_version) VALUES (1, 1);
CREATE TABLE arc_graph_version (process_id VARCHAR(80) NOT NULL, process_version INTEGER NOT NULL, definition_json TEXT NOT NULL, PRIMARY KEY (process_id, process_version), CONSTRAINT arc_graph_version_positive CHECK (process_version > 0));
CREATE TABLE arc_graph_head (process_id VARCHAR(80) PRIMARY KEY, active_version INTEGER NOT NULL, draft_revision BIGINT NOT NULL, draft_base_version INTEGER NOT NULL, draft_json TEXT NOT NULL, FOREIGN KEY (process_id, active_version) REFERENCES arc_graph_version(process_id, process_version), CONSTRAINT arc_graph_draft_positive CHECK (draft_revision >= 0 AND draft_base_version > 0));
CREATE TABLE arc_graph_request (request_id VARCHAR(128) PRIMARY KEY, process_id VARCHAR(80) NOT NULL, process_version INTEGER NOT NULL, command_revision BIGINT NOT NULL, applicant_id VARCHAR(80) NOT NULL, submission_key VARCHAR(160) NOT NULL, request_status VARCHAR(16) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, request_json TEXT NOT NULL, UNIQUE (process_id, applicant_id, submission_key), FOREIGN KEY (process_id, process_version) REFERENCES arc_graph_version(process_id, process_version), CONSTRAINT arc_graph_revision_positive CHECK (command_revision >= 0), CONSTRAINT arc_graph_request_status CHECK (request_status IN ('PENDING','APPROVED','REJECTED')));
CREATE TABLE arc_graph_event (request_id VARCHAR(128) NOT NULL, event_sequence BIGINT NOT NULL, event_json TEXT NOT NULL, PRIMARY KEY (request_id, event_sequence), FOREIGN KEY (request_id) REFERENCES arc_graph_request(request_id), CONSTRAINT arc_graph_event_positive CHECK (event_sequence > 0));
CREATE TABLE arc_graph_command (request_id VARCHAR(128) NOT NULL, command_id VARCHAR(160) NOT NULL, command_revision BIGINT NOT NULL, command_json TEXT NOT NULL, PRIMARY KEY (request_id, command_id), UNIQUE (request_id, command_revision), FOREIGN KEY (request_id) REFERENCES arc_graph_request(request_id), CONSTRAINT arc_graph_command_positive CHECK (command_revision > 0));
CREATE TABLE arc_graph_task (request_id VARCHAR(128) NOT NULL, task_id VARCHAR(200) NOT NULL, node_id VARCHAR(80) NOT NULL, task_status VARCHAR(16) NOT NULL, task_json TEXT NOT NULL, PRIMARY KEY (request_id, task_id), FOREIGN KEY (request_id) REFERENCES arc_graph_request(request_id), CONSTRAINT arc_graph_task_status CHECK (task_status IN ('ACTIVE','COMPLETED','REJECTED','CANCELLED')));
CREATE TABLE arc_graph_task_member (request_id VARCHAR(128) NOT NULL, task_id VARCHAR(200) NOT NULL, actor_id VARCHAR(80) NOT NULL, pending BOOLEAN NOT NULL, handled BOOLEAN NOT NULL, PRIMARY KEY (request_id, task_id, actor_id), FOREIGN KEY (request_id, task_id) REFERENCES arc_graph_task(request_id, task_id));
CREATE TABLE arc_graph_request_member (request_id VARCHAR(128) NOT NULL, actor_id VARCHAR(80) NOT NULL, pending BOOLEAN NOT NULL, handled BOOLEAN NOT NULL, PRIMARY KEY (request_id, actor_id), FOREIGN KEY (request_id) REFERENCES arc_graph_request(request_id));
CREATE INDEX arc_graph_task_actor ON arc_graph_task_member(actor_id, pending, request_id);
CREATE INDEX arc_graph_member_actor ON arc_graph_request_member(actor_id, pending, request_id);
